public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int Q = sc.nextInt();
    boolean[] teeth = new boolean[N];

    for (int i = 0; i < Q; i++) {
        int treatment = sc.nextInt();
        teeth[treatment - 1] = !teeth[treatment - 1];
    }

    int count = 0;
    for (boolean tooth : teeth) {
        if (tooth) {
            count++;
        }
    }

    System.out.println(count);
}
